    let [min, max] = box;
    let [x, y] = min, w = max[0] - x, h = max[1] - y;
    return `M${x} ${y}v${h}h${w}v${-h}z M${x + margin} ${y + margin}h${w - 2 * margin}v${h - 2 * margin}h${-(w - 2 * margin)}z`
